 $rows[]=[++$i,export_name143($s),export_data143('job_title',(string)($c['job_title35']??$s['job_title'])),export_data143('department',(string)($c['department']??$s['department'])),$c['joining_date35']??$s['hired_on'],$c['working_days']??null,$leaveDays,$c['deduct_days']??null,$c['extra_days']??null,(float)($c['reference_salary35']??$c['salary']),(float)($a['telephone']??0),(float)($a['transport']??0),(float)($a['housing']??0),$friday,round($comm['delivery_contract'],3),round($gross,3),$extra,round($gross-$cash-array_sum($comm),3),round($cash,3),round($comm['sales'],3),round($comm['collection'],3),$debt,$sick,round($late,3),$penalty,round($otherDeduct,3),(float)$c['deduction'],(float)$p['net_amount'],export_text143($p['status']),round($comm['sales_agent'],3)];if($hasAfaq123)$rows[count($rows)-1]=array_merge($rows[count($rows)-1],[(float)($c['afaq_commission123']??0),(float)($c['afaq_extra_commission123']??0)]);}
